async function api<T>(path:string, method='GET', body?:unknown):Promise<T> {
  const r = await fetch('/api'+path, {method, headers:body instanceof FormData ? {} : {'Content-Type':'application/json'}, body:body===undefined ? undefined : body instanceof FormData ? body : JSON.stringify(body)});
  const data = await r.json();
  if (!r.ok) throw new Error(typeof data.detail === 'string' ? data.detail : '请求内容无效，请检查输入');
  return data;
}
type RewriteResult = {title:string;script:string;chars:number;fixes:string[];check_numbers:string[];unmatched_fixes?:number;checked?:boolean};
const fileUrl = (pid:string,path:string) => `/api/projects/${pid}/files/${path.split('/').map(encodeURIComponent).join('/')}`;
const external = (s?:string) => s && /^https?:\/\//i.test(s) ? s : undefined;
const seconds = (n:number) => `${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
const active = (j:Job) => ['queued','running'].includes(j.status);
const sourceNames:Record<string,string> = {local:'本地素材',upload:'本地导入',commons:'Wikimedia',publisher_image:'原页图注图片',bing:'网页搜图',tavily:'联网搜图',pixabay:'Pixabay',pexels:'Pexels',coverr:'Coverr',tencent:'腾讯视频',bilibili:'哔哩哔哩',chinanews:'中新网视频',chinanews_image:'中新网图片',cctv:'央视视频',youtube:'YouTube',dailymotion:'Dailymotion',nasa:'NASA',archive:'Internet Archive',web_video:'网页视频链接',demo:'内置示意图'};

function App() {
 const [projects,setProjects] = useState<Summary[]>([]), [project,setProject] = useState<Project|null>(null);
 const [jobs,setJobs] = useState<Job[]>([]), [tab,setTab] = useState('script'), [selected,setSelected] = useState('');
 const [error,setError] = useState(''), [notice,setNotice] = useState(''), [loading,setLoading] = useState(false);
 const [settings,setSettings] = useState(false), [exporting,setExporting] = useState(false), [system,setSystem] = useState<Record<string,any>>({});
 const [draft,setDraft] = useState({title:'',script:'',style:'',requirements:'',aspect:'16:9',media_policy:'video_preferred',min_video_ratio:.8,min_video_height:720}), [mode,setMode] = useState('auto');
 const [preview,setPreview] = useState<Export|null>(null);
 const [original,setOriginal]=useState<null|{title:string;script:string}>(null), [rewriteInfo,setRewriteInfo]=useState<RewriteResult|null>(null);
 const [batch,setBatch]=useState(false), [newsPanel,setNewsPanel]=useState(false), [filmPreview,setFilmPreview]=useState(false);
 const [indexLibrary,setIndexLibrary]=useState(false);
 const [view,setView]=useState<'home'|'works'|'project'>('home');
 const saveShotRef=useRef<null|(()=>Promise<void>)>(null);
 const [shotDirty,setShotDirty]=useState(false);
 const scriptDirty=!!project&&Object.entries(draft).some(([k,v])=>v!==project[k as keyof Project]);
 useEffect(()=>{const guard=(e:BeforeUnloadEvent)=>{if(scriptDirty||shotDirty){e.preventDefault();e.returnValue=''}};window.addEventListener('beforeunload',guard);return()=>window.removeEventListener('beforeunload',guard)},[scriptDirty,shotDirty]);
 const current = project?.shots.find(s=>s.id===selected) ?? project?.shots[0];
 const [rewriting,setRewriting]=useState<string[]>([]);    // projects with an AI rewrite in flight
 const running = jobs.find(active), busy = loading || !!running || (!!project && rewriting.includes(project.id));
 const projectRef = useRef(project); projectRef.current=project;
 const loadProjects = useCallback(async()=>setProjects(await api<Summary[]>('/projects')),[]);
 const refresh = useCallback(async(id:string)=>{
   const [p,j] = await Promise.all([api<Project>('/projects/'+id),api<Job[]>('/projects/'+id+'/jobs')]);
   // A poll answered after a save carries an older revision: never roll the editor back to it.
   if (projectRef.current?.id===id && p.revision>=(projectRef.current?.revision||0)) {setProject(p);setJobs(j)}
   setProjects(rows=>rows.map(row=>row.id===id?{...row,title:p.title,shot_count:p.shots.length,script_length:p.script.length,aspect:p.aspect,revision:p.revision}:row));
 },[]);
 // While any video is being made, keep the project list (its progress marks) current.
 const anyRunning=projects.some(p=>p.job&&['queued','running'].includes(p.job.status));
 useEffect(()=>{if(!anyRunning)return;const t=setInterval(()=>loadProjects().catch(()=>{}),5000);return()=>clearInterval(t)},[anyRunning,loadProjects]);
 useEffect(()=>{loadProjects().catch(e=>setError(e.message));api<Record<string,any>>('/system').then(setSystem).catch(e=>setError(e.message))},[loadProjects]);
 useEffect(()=>{
  if(!project) return;
  const id=project.id; const timer=setInterval(()=>refresh(id).catch(()=>{}),1800);
  return ()=>clearInterval(timer);
 },[project?.id,refresh]);
 useEffect(()=>{
  if(project) {setDraft({title:project.title,script:project.script,style:project.style,requirements:project.requirements,aspect:project.aspect,media_policy:project.media_policy||'mixed',min_video_ratio:project.min_video_ratio??.8,min_video_height:project.min_video_height??720});setSelected(project.shots[0]?.id||'');setPreview(null);setOriginal(null);setRewriteInfo(null);setNotice('')}
 },[project?.id]);
 // When a whole-video or export job finishes, say so and show the new video.
 const watched=useRef<{id:string;kind:string}|null>(null);
 useEffect(()=>{
  if(running){watched.current={id:running.id,kind:running.kind};return}
  const last=watched.current;if(!last)return;watched.current=null;
  const done=jobs.find(j=>j.id===last.id);
  if(done?.status==='completed'&&['produce','render'].includes(last.kind)){setPreview(null);setTab(last.kind==='produce'?'overview':'exports');if(last.kind==='render')setNotice('视频已导出，并已保存到成片文件夹。');loadProjects().catch(()=>{})}
 },[running?.id,jobs]);
 // A job (the news rewrite stage) may write the script/title on the server: take it into the draft
 // unless the user has edited that field since it was loaded.
 const synced=useRef({id:'',title:'',script:''});
 useEffect(()=>{
  if(!project)return;
  const last=synced.current;
  if(last.id===project.id)setDraft(d=>({...d,script:d.script===last.script?project.script:d.script,title:d.title===last.title?project.title:d.title}));
  synced.current={id:project.id,title:project.title,script:project.script};
 },[project?.id,project?.script,project?.title]);
 const perform = async(fn:()=>Promise<void>) => {setLoading(true);setError('');try{await fn()}catch(e){setError((e as Error).message)}finally{setLoading(false)}};
 const savePending=async()=>{if(scriptDirty)await saveDraft();await saveShotRef.current?.()};
 const navigate=(next:string)=>perform(async()=>{await savePending();setTab(next)});
 const chooseProject = async(id:string)=>perform(async()=>{
  await savePending();
  const p=await api<Project>('/projects/'+id),js=await api<Job[]>('/projects/'+id+'/jobs');setProject(p);setJobs(js);setTab(p.exports.length||js.some(j=>j.kind==='produce')?'overview':p.shots.length?'board':'script');setView('project');
 });
 const create = async(demo=false)=>perform(async()=>{
  await savePending();
  const p=await api<Project>(demo?'/demo':'/projects','POST',demo?undefined:{title:'新的视频项目'});setProject(p);setJobs([]);setTab(demo?'board':'script');setView('project');await loadProjects();
 });
 const saveDraft = async()=>{
  if(!project) return;
  // An untitled project takes its first sentence as the name.
  const first=draft.script.trim().split(/[\n。！？!?，,]/)[0]?.trim().slice(0,30);
  const body=(!draft.title.trim()||draft.title==='新的视频项目')&&first?{...draft,title:first}:draft;
  const p=await api<Project>('/projects/'+project.id,'PATCH',body);setProject(p);setDraft(d=>({...d,title:p.title}));await loadProjects();return p;
 };
 const job = async(kind:string,extra:Record<string,unknown>={})=>{
  if(!project)return;
  await api('/projects/'+project.id+'/jobs','POST',{kind,...extra});
  await refresh(project.id);
 };
 const upload = async(files:FileList|null,role='asset',shotId='')=>{const selectedFiles=Array.from(files||[]);if(!project||!selectedFiles.length)return;await perform(async()=>{
  await savePending();
  for(const f of selectedFiles){const body=new FormData();body.append('file',f);body.append('role',role);body.append('shot_id',shotId);setProject(await api<Project>('/projects/'+project.id+'/upload','POST',body))}
  setNotice(role==='narration'?'已按字数分配音频，请试听并调整镜头时长':'文件已导入');
 })};
 const patchShot = async(sid:string,values:Record<string,unknown>)=>{if(project)setProject(await api<Project>(`/projects/${project.id}/shots/${sid}`,'PATCH',values))};
 const duration = project?.shots.reduce((n,s)=>n+s.duration,0)||0;
 const approved = project?.shots.filter(s=>s.approved).length||0;
 const voiced = project?.full_audio ? project.shots.length : project?.shots.filter(s=>s.audio).length||0;
 return <div className="app-shell">
  <aside className="sidebar">
   <div className="brand"><div className="brand-icon"><Aperture size={24}/></div><div><strong>镜稿</strong><span>文案一键成片</span></div></div>
   <nav className="main-nav">
    <button className={view==='home'?'on':''} onClick={()=>perform(async()=>{await savePending();setView('home')})}><Sparkles size={17}/>一键成片</button>
    <button className={view==='works'?'on':''} onClick={()=>perform(async()=>{await savePending();await loadProjects();setView('works')})}><LayoutGrid size={17}/>我的作品</button>
    <button onClick={()=>perform(async()=>{await savePending();setNewsPanel(true)})}><Newspaper size={17}/>新闻选题</button>
    <button onClick={()=>perform(async()=>{await savePending();setBatch(true)})}><Layers3 size={17}/>批量制作</button>
    <button onClick={()=>perform(async()=>{await savePending();setIndexLibrary(true)})}><Database size={17}/>素材库</button>
   </nav>
   <div className="section-label">最近</div>
   <nav className="project-list">{projects.map(p=><button key={p.id} aria-label={p.title} title={p.title} className={'project-item '+(view==='project'&&project?.id===p.id?'selected':'')} onClick={()=>chooseProject(p.id)}><Film size={17}/><div><strong>{p.title}</strong><small>{p.video?'已出片':p.shot_count?p.shot_count+' 个镜头':'草稿'}</small></div>{p.job&&['queued','running'].includes(p.job.status)&&<Loader2 className="spin" size={13}/>}</button>)}{!projects.length&&<p className="sidebar-hint">做好的视频会出现在这里。</p>}</nav>
   <div className="sidebar-bottom"><div className="local-status"><span className="green-dot"/>本地工作台 <small title={system.summary||''}>{system.full?'显卡加速已开启':system.nvenc?'显卡编码已开启':system.nvidia?'显卡加速未开启（见设置）':'CPU 合成'}</small><AssistBadge/></div><button className="settings-btn" onClick={()=>setSettings(true)}><Settings2 size={17}/>设置<ChevronRight size={15}/></button><div className="more-links"><button onClick={()=>create()} disabled={loading}>空白项目</button></div><small className="version">v{system.version||"0.4.2"} 测试版 · 项目保存在本机</small></div>
  </aside>
  <main>
   <header className="topbar"><div className="breadcrumb">{view==='home'?<span>一键成片</span>:view==='works'?<span>我的作品</span>:<><button className="crumb" onClick={()=>perform(async()=>{await savePending();await loadProjects();setView('works')})}>我的作品</button><ChevronRight size={14}/><span>{project?.title}</span></>}</div><div className="top-actions"><span className="local-chip"><Monitor size={13}/> 本地运行</span>{view==='project'&&project&&<button className="secondary small" disabled={busy||!(draft.script.trim()||project.news?.text||project.source_audio)} onClick={()=>perform(async()=>{await savePending();await job('produce',{resolution:'1080p'});setTab('overview')})}><Sparkles size={15}/>生成视频</button>}{view==='project'&&project&&<button className="primary small" disabled={busy||!project.shots.length} onClick={()=>perform(async()=>{await savePending();setExporting(true)})}><Download size={15}/>导出视频</button>}</div></header>
   {error&&<div role="alert" className="message error">{error}<button aria-label="关闭错误" onClick={()=>setError('')}><X size={16}/></button></div>}
   {notice&&<div role="status" className="message notice">{notice}<button aria-label="关闭提示" onClick={()=>setNotice('')}><X size={16}/></button></div>}
   {view==='home'?<QuickStart started={id=>{chooseProject(id);loadProjects().catch(()=>{})}} openNews={()=>setNewsPanel(true)}/>:view==='works'||!project?<WorksGrid projects={projects} open={chooseProject} create={()=>setView('home')}/>:
   <>
    <div className="project-header"><div><h1>{project.title}</h1></div><div className="project-metrics"><div><strong>{project.shots.length.toString().padStart(2,'0')}</strong><span>个分镜</span></div><div><strong>{seconds(duration)}</strong><span>预计时长</span></div><div><strong>{project.aspect}</strong><span>画面比例</span></div></div></div>
    <div className="tabbar">{[['overview','成片'],['script','文稿'],['board','分镜精修'],['library','素材'],['exports','导出记录']].map(([id,name])=><button key={id} className={tab===id?'active':''} onClick={()=>navigate(id)}>{name}{id==='exports'&&project.exports.length>0&&<b>{project.exports.length}</b>}</button>)}</div>
    <ModelCostBar report={project.model_costs} settings={()=>setSettings(true)}/>
    {running&&tab!=='overview'&&<div className="job-progress"><Loader2 className="spin" size={17}/><span>{running.message}</span><div className="progress-track"><i style={{width:running.progress+'%'}}/></div><small>{Math.round(running.progress)}%</small><button onClick={()=>perform(async()=>{await api('/jobs/'+running.id+'/cancel','POST');await refresh(project.id)})} disabled={!!running.cancel}>取消任务</button></div>}
    {!running&&tab!=='overview'&&jobs[0]&&['failed','interrupted','needs_review','cancelled'].includes(jobs[0].status)&&<div className="job-error"><div><strong>{jobs[0].message}</strong><p>{jobs[0].error}</p></div><button className="secondary small" onClick={()=>perform(async()=>{await api('/jobs/'+jobs[0].id+'/retry','POST');await refresh(project.id)})}><RefreshCw size={14}/>重试</button></div>}
    <div className="workspace">{project.script_changed&&<div className="inline-note warning">原稿已修改，当前分镜仍是旧版本。请重新规划分镜后再导出。</div>}
     {tab==='overview'&&<ProduceView project={project} jobs={jobs} act={(path,body)=>perform(async()=>{await api(path,'POST',body);await refresh(project.id)})} refine={()=>setTab('board')} again={()=>setView('home')}/>}
     {tab==='script'&&<div className="script-layout"><section className="panel script-panel"><div className="panel-heading"><h2>口播文稿</h2><div className="heading-actions"><button className="text-link" disabled={busy||!(draft.script.trim()||project.news?.text)} title="把新闻或草稿改写成口播稿：保留事实，换一种说法，每行一句" onClick={async()=>{const before={title:draft.title,script:draft.script},pid=project.id,source=draft.script.trim()||project.news?.text||'';setError('');setRewriting(r=>[...r,pid]);setNotice('正在用 AI 改写并核对事实，约 20-40 秒…');try{const r=await api<RewriteResult>('/rewrite','POST',{text:source,title:draft.title,aspect:draft.aspect,minutes:project.news?.minutes??null,project_id:pid});if(projectRef.current?.id!==pid)return;setOriginal(before);setRewriteInfo(r);setDraft(d=>({...d,script:r.script,title:!d.title.trim()||d.title==='新的视频项目'||d.title===project.news?.title?r.title||d.title:d.title}))}catch(e){if(projectRef.current?.id===pid)setError((e as Error).message)}finally{setRewriting(r=>r.filter(x=>x!==pid));if(projectRef.current?.id===pid)setNotice(n=>n.startsWith('正在用 AI')?'':n)}}}>{rewriting.includes(project.id)?<Loader2 className="spin" size={13}/>:<WandSparkles size={13}/>}AI 洗稿</button><label className={'text-link'+(busy?' disabled':'')}>导入 TXT<input type="file" accept=".txt,.md" hidden disabled={busy} onChange={async e=>{const f=e.target.files?.[0];if(f){const text=await f.text();setDraft(d=>({...d,script:text}));}e.target.value=''}}/></label></div></div>{(project.plan_info as any)?.normalize?.model&&project.script_original&&<div className="inline-note rewrite-note">文稿已按标准整理后再配音和分镜：补全标点、按语义断句、编号改成口语{((project.plan_info as any).normalize.changes||[]).length?`、改正 ${(project.plan_info as any).normalize.changes.length} 处错字`:''}。<button disabled={busy} onClick={()=>{if(window.confirm('恢复成整理前的原稿？需要重新规划分镜和配音。'))setDraft(d=>({...d,script:project.script_original||d.script}))}}>恢复原稿</button>{!!((project.plan_info as any).normalize.changes||[]).length&&<details><summary>查看改正的字词</summary>{(project.plan_info as any).normalize.changes.map((c:{from:string;to:string},i:number)=><p key={i}>{c.from} → {c.to}</p>)}</details>}</div>}
     {!original&&project.news&&<div className="inline-note rewrite-note">新闻来源：{project.news.url?<a href={project.news.url} target="_blank" rel="noreferrer noopener">{project.news.title||project.news.source}</a>:project.news.title}{project.news.rewrite?<>{' · 已自动洗稿 '+project.news.rewrite.chars+' 字'}{project.news.rewrite.checked===false?' · 事实核对未完成，请对照原文':(project.news.rewrite.fixes.length?` · 对照原文修正 ${project.news.rewrite.fixes.length} 处`:project.news.rewrite.unmatched_fixes?'':' · 对照原文未发现事实错误')+(project.news.rewrite.unmatched_fixes?` · 另有 ${project.news.rewrite.unmatched_fixes} 处核对意见没能对应到具体句子，请对照原文`:'')}{project.news.rewrite.check_numbers.length?` · 请核对原文中没有的数字：${project.news.rewrite.check_numbers.join('、')}`:''}</>:!project.script.trim()?' · 尚未洗稿：点“自动生成整片”会先洗稿再出片，或点“AI 洗稿”先看稿':''}<details><summary>新闻原文</summary><p className="news-original">{project.news.text}</p>{!!project.news.rewrite?.fixes.length&&project.news.rewrite.fixes.map((f,i)=><p key={i}>修正：{f}</p>)}</details></div>}
     {original&&<div className="inline-note rewrite-note">已用 AI 改写为口播稿 · {rewriteInfo?.chars} 字{rewriteInfo&&rewriteInfo.checked===false?' · 事实核对未完成，请自行对照原文':(rewriteInfo?.fixes.length?` · 对照原文自动修正 ${rewriteInfo.fixes.length} 处事实`:rewriteInfo?.unmatched_fixes?'':' · 对照原文未发现事实错误')+(rewriteInfo?.unmatched_fixes?` · 另有 ${rewriteInfo.unmatched_fixes} 处核对意见没能对应到具体句子，请自行对照原文`:'')}{rewriteInfo?.check_numbers.length?` · 请核对原文中没有的数字：${rewriteInfo.check_numbers.join('、')}`:''}<button onClick={()=>{setDraft(d=>({...d,...original}));setOriginal(null);setRewriteInfo(null)}}>恢复原稿</button>{!!rewriteInfo?.fixes.length&&<details><summary>查看修正</summary>{rewriteInfo.fixes.map((f,i)=><p key={i}>{f}</p>)}</details>}</div>}<input aria-label="项目名称" className="title-input" placeholder="给视频起个名字" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} disabled={busy}/><textarea aria-label="口播文稿" className="script-editor" placeholder="粘贴你的完整口播稿……&#10;&#10;保留具体的人物、地点、时间和数据，便于找到准确的画面。" value={draft.script} onChange={e=>setDraft({...draft,script:e.target.value})} disabled={busy}/><div className="editor-footer"><span>{draft.script.length} 字 · 原稿保留在项目中</span><button className="secondary small" onClick={()=>perform(async()=>{await saveDraft();setNotice('文稿已保存')})} disabled={busy}><Save size={14}/>保存文稿</button></div></section><section className="panel plan-panel"><div className="panel-heading"><h2>制作方案</h2><WandSparkles size={18}/></div><label>画面比例<div className="segmented">{['16:9','9:16'].map(a=><button key={a} disabled={busy} className={draft.aspect===a?'selected':''} onClick={()=>setDraft({...draft,aspect:a})}><span className={a==='16:9'?'ratio wide':'ratio tall'}/>{a} {a==='16:9'?'横屏':'竖屏'}</button>)}</div></label><label>视觉风格<input value={draft.style} disabled={busy} onChange={e=>setDraft({...draft,style:e.target.value})}/></label><label>选材要求<textarea rows={4} placeholder="例如：中国铁路场景，2023 年以后，避免国外列车与无关人群" value={draft.requirements} disabled={busy} onChange={e=>setDraft({...draft,requirements:e.target.value})}/></label><label>素材方案<select value={draft.media_policy} disabled={busy} onChange={e=>setDraft({...draft,media_policy:e.target.value})}><option value="video_preferred">实拍/录屏为主 · 少量图片/示意</option><option value="video_only">全部使用实拍/录屏视频</option><option value="mixed">图片与视频自由搭配</option></select></label>{draft.media_policy==='video_preferred'&&<label>实拍/录屏最低时长占比 {Math.round(draft.min_video_ratio*100)}%<input type="range" min="0.5" max="1" step="0.05" value={draft.min_video_ratio} disabled={busy} onChange={e=>setDraft({...draft,min_video_ratio:Number(e.target.value)})}/></label>}<label>视频源最低清晰度<select value={draft.min_video_height} disabled={busy} onChange={e=>setDraft({...draft,min_video_height:Number(e.target.value)})}><option value="1080">1080p</option><option value="720">720p · 推荐</option><option value="480">480p · 接受较低清晰度</option><option value="270">270p · 仅建议流程预览</option></select></label><p className="muted-note">按实际可播放时长统计。动画/混合示意、类型待核、图片运镜与末帧定格不计入实拍/录屏目标；混合方案不限制比例。缺少人物或本场依据时保留缺口。</p><label>分镜方式<select value={mode} disabled={busy} onChange={e=>setMode(e.target.value)}><option value="auto">自动选择 · 已配密钥时使用 AI</option><option value="model">AI 规划 · 通义千问等兼容接口</option><option value="rules">规则切分 · 无需联网</option></select></label><p className="muted-note">原稿可用时直接分镜。每镜保存主体、地点、年代和排除条件，后续可以逐项修改。</p><button className="primary full" disabled={busy||!draft.script.trim()} onClick={()=>perform(async()=>{if(project.shots.length&&!window.confirm('重新规划将替换现有分镜、选材和配音关联；素材与旧导出仍保留。继续吗？'))return;await saveDraft();await job('plan',{mode,replace:project.shots.length>0});setTab('board')})}><Sparkles size={17}/>{project.shots.length?'重新规划分镜':'生成分镜'}<ArrowRight size={17}/></button></section></div>}
     {tab==='board'&&(!project.shots.length?<div className="empty-state"><Layers3 size={42}/><h2>{running?'正在规划你的分镜':'先为文稿规划分镜'}</h2><p>每一个镜头都有独立的口播、画面要求和素材。</p><button className="secondary" onClick={()=>setTab('script')}>返回文稿与方案</button></div>:<>
      <div className="board-toolbar"><div><h2>分镜工作台 <span>{approved}/{project.shots.length} 已确认</span></h2><p>{project.plan_info?.message||'逐镜核对素材与口播'}</p></div><div className="toolbar-actions"><button className="primary small" disabled={loading} title="不用先导出：按导出的时间线依次播放全部分镜" onClick={()=>perform(async()=>{await savePending();setFilmPreview(true)})}><Play size={15}/>预览全片</button><button className="secondary small" disabled={busy} onClick={()=>perform(async()=>{await savePending();await job('search')})}><Search size={15}/>搜索全部素材</button><button className="secondary small" disabled={busy} onClick={()=>perform(async()=>{await savePending();await job('match')})}><Sparkles size={15}/>自动配素材</button><button className="secondary small" disabled={busy||!!project.full_audio} onClick={()=>perform(async()=>{await savePending();await job('voice')})}><Mic size={15}/>补全配音</button><button className="secondary small" disabled={busy} title="一次生成整段音轨，减少调用；字幕时序按字数粗分，需试听校准" onClick={()=>perform(async()=>{await savePending();if(!window.confirm('整段配音只调用一次，并按字数粗分镜头时长；需要试听校准字幕。已有配音会被替换，素材须按新时长复核。继续生成？'))return;await job('voice_full',{replace:true})})}><Mic size={15}/>整段快速配音</button></div></div>
      {project.match_info&&!running&&<div className="inline-note"><strong>上轮匹配 {project.match_info.selected}/{project.match_info.shots} 镜 · {project.match_info.elapsed_seconds.toFixed(1)} 秒</strong>{!!project.match_info.unmatched?.length&&<span> · 仍有 {project.match_info.unmatched.length} 镜需要补充，具体原因见各镜头。</span>}{!!project.match_info.source_failures?.length&&<details><summary>查看本轮来源问题</summary>{project.match_info.source_failures.map((reason,i)=><p key={i}>{reason}</p>)}</details>}</div>}
      <CompositionBar project={project}/><div className="inline-note compact">{project.full_audio?<>配音：{project.full_audio.title} · {project.caption_alignment?'字幕已按真实音轨对齐':'导出前会在本地对齐字幕'}</>:'字幕会显示在分镜预览，并烧录进导出视频'}{approved<project.shots.length&&<button disabled={busy} onClick={()=>perform(async()=>{await savePending();setProject(await api<Project>(`/projects/${project.id}/approve-verified`,'POST'))})}>确认已通过画面核验的镜头</button>}</div>
      <div className="board-layout"><div className="shot-list">{project.shots.map((s,i)=>{const a=project.assets.find(a=>a.id===s.selected_asset);return <button key={s.id} className={'shot-card '+(current?.id===s.id?'selected':'')} onClick={()=>perform(async()=>{await savePending();setSelected(s.id)})}><div className="shot-thumb">{a?.thumbnail?<img src={fileUrl(project.id,a.thumbnail)} alt={a.title}/>:<ImageIcon size={26}/>}{s.frame_crop?.overlays?.length&&s.crop_asset===a?.id?<em className="clean-badge" title="已自动去水印 / 挡字幕">去水印</em>:null}<span>{seconds(s.duration)}</span></div><div className="shot-card-text"><div><b>分镜 {String(i+1).padStart(2,'0')}</b>{s.locked?<Lock size={12}/>:s.approved?<CheckCircle2 size={14} className="success"/>:<span className="pending-dot"/>}</div><p>{s.narration}</p><small>{s.approved?'画面已确认':a?'待审核画面':'待选择素材'} · {s.audio||project.full_audio?'配音就绪':'待配音'}</small></div></button>})}</div>
      {current&&<ShotEditor key={current.id} project={project} shot={current} index={project.shots.indexOf(current)} busy={busy} run={perform} patch={patchShot} job={job} upload={upload} onProject={setProject} saveRef={saveShotRef} onDirty={setShotDirty}/>}
      </div>
     </>)}
     {tab==='library'&&<><div className="board-toolbar"><div><h2>项目素材 <span>{project.assets.length} 个文件</span></h2><p>本地图片、视频与音轨，保留来源说明，供分镜重复使用。</p></div><label className={'primary small '+(busy?'disabled':'')}><Upload size={15}/>导入素材<input type="file" multiple accept="image/jpeg,image/png,image/webp,video/*,audio/*" hidden disabled={busy} onChange={e=>{upload(e.target.files);e.target.value=''}}/></label></div><div className="audio-tools"><label className="secondary small"><Mic size={15}/>导入整段配音<input type="file" accept="audio/*,video/mp4" hidden disabled={busy} onChange={e=>{upload(e.target.files,'narration');e.target.value=''}}/></label><label className="secondary small"><Music2 size={15}/>导入背景音乐<input type="file" accept="audio/*" hidden disabled={busy} onChange={e=>{upload(e.target.files,'music');e.target.value=''}}/></label><span>{project.music?'配乐：'+project.music.title:'配乐可选'}</span></div>{project.full_audio&&<div className="inline-note">{project.full_audio.title} · {project.caption_alignment?'字幕已在本地按真实音轨对齐。':'字幕将在导出前用本地音轨对齐。'}<button disabled={busy} onClick={()=>perform(async()=>setProject(await api<Project>(`/projects/${project.id}/audio/full_audio`,'DELETE')))}>移除整段配音</button></div>}{project.music&&<button className="text-link" disabled={busy} onClick={()=>perform(async()=>setProject(await api<Project>(`/projects/${project.id}/audio/music`,'DELETE')))}>移除背景音乐</button>}<div className="library-grid">{project.assets.map(a=><div className="library-card" key={a.id}><div className="library-thumb">{a.thumbnail?<img src={fileUrl(project.id,a.thumbnail)} alt={a.title}/>:<Mic size={36}/>}<span>{a.kind==='image'?'图片':a.kind==='video'?'视频':'音频'}</span></div><h3>{a.title}</h3><p>{a.license}</p><details><summary>编辑来源说明</summary><AssetMetadata asset={a} busy={busy} save={v=>perform(async()=>setProject(await api<Project>(`/projects/${project.id}/assets/${a.id}`,'PATCH',v)))}/></details></div>)}</div>{!project.assets.length&&<div className="empty-state"><FolderOpen size={40}/><h2>还没有项目素材</h2><p>上传图片或视频，也可以在分镜中搜索在线候选。</p></div>}</>}
     {tab==='exports'&&<><div className="board-toolbar"><div><h2>导出记录</h2><p>每次导出保留独立版本，附字幕与素材来源清单。</p></div></div>{!project.exports.length?<div className="empty-state"><Clapperboard size={40}/><h2>你的第一条视频即将诞生</h2><p>确认画面、准备配音后，点击右上角导出视频。</p></div>:<div className="exports-layout"><div className="export-preview"><video key={(preview||project.exports[0]).id} controls src={fileUrl(project.id,(preview||project.exports[0]).path)}/></div><div>{project.exports.map(e=><div className={'export-card '+(preview?.id===e.id?'selected':'')} key={e.id}><button className="export-title" onClick={()=>setPreview(e)}><Film size={17}/>{new Date(e.created*1000).toLocaleString('zh-CN')}</button><p>{e.width} × {e.height} · {seconds(e.duration)} · {e.encoder==='nvenc'?'NVIDIA':'CPU'}{e.silent_preview?' · 预览模式':''}</p><div><a className="secondary small" href={fileUrl(project.id,e.path)+'?download=true'}><Download size={14}/>MP4</a><a className="text-link" href={fileUrl(project.id,e.bundle)+'?download=true'}>完整交付包</a><a className="text-link" href={fileUrl(project.id,e.path.replace(/video\.mp4$/,'subtitles.srt'))+'?download=true'}>SRT 字幕</a></div></div>)}</div></div>}</>}
    </div>
    <footer className="statusbar"><span><span className="green-dot"/>{scriptDirty||shotDirty?'有未保存修改':'项目已保存'} · 修订 {project.revision}</span><span>画面 {approved}/{project.shots.length} · 配音 {voiced}/{project.shots.length}</span></footer>
   </>}
  </main>
  {filmPreview&&project&&<FilmPreview project={project} close={()=>setFilmPreview(false)} edit={id=>{setFilmPreview(false);setTab('board');setSelected(id);setTimeout(()=>document.querySelector('.shot-card.selected')?.scrollIntoView({block:'center'}),80)}}/>}
  {newsPanel&&<NewsPanel close={()=>setNewsPanel(false)} openProject={chooseProject} onCreated={()=>{loadProjects()}}/>}
  {batch&&<BatchPanel close={()=>setBatch(false)} openProject={chooseProject} onCreated={()=>{loadProjects()}}/>}
  {indexLibrary&&<FootagePanel close={()=>setIndexLibrary(false)}/>}
  {settings&&<SettingsModal close={()=>setSettings(false)} onError={setError}/>}
  {exporting&&project&&<ExportModal close={()=>setExporting(false)} preview={()=>{setExporting(false);setFilmPreview(true)}} project={project} submit={opts=>perform(async()=>{await job('render',opts);setExporting(false);setTab('exports')})}/>}
 </div>
}

function CompositionBar({project}:{project:Project}) {
 const c=composition(project);
 const width=(seconds:number)=>`${c.total_seconds?seconds/c.total_seconds*100:0}%`;
 const warnings=[c.identity_pending.length&&`人物/事件待核 ${c.identity_pending.length} 镜`,c.short_video_shots.length&&`视频时长不足 ${c.short_video_shots.length} 镜`,c.low_resolution_shots.length&&`视频清晰度不足 ${c.low_resolution_shots.length} 镜`,c.unclassified_video_shots.length&&`视频类型需核 ${c.unclassified_video_shots.length} 镜`].filter(Boolean);
 return <div className="composition"><div><Film size={17}/><strong>{c.legacy_video_seconds?'视频（含手动选片）':'实拍/录屏视频'} {Math.round(c.video_ratio*100)}%</strong><span>{seconds(c.video_seconds)} / {seconds(c.total_seconds)}</span><span>图片 {seconds(c.image_seconds)}</span>{c.illustration_video_seconds>0&&<span>动画/混合示意 {seconds(c.illustration_video_seconds)}</span>}{c.unclassified_video_seconds>0&&<span>类型待核 {seconds(c.unclassified_video_seconds)}</span>}{project.media_policy!=='mixed'&&<span className={c.meets_target?'success':'composition-gap'}>目标 ≥ {Math.round(c.target_video_ratio*100)}%</span>}</div>
  <div className="composition-track"><i title="实拍/录屏与沿用统计的旧项目视频" style={{width:width(c.video_seconds)}}/><i title="动画/混合示意" style={{width:width(c.illustration_video_seconds),background:'#9293bc'}}/><i title="类型待核" style={{width:width(c.unclassified_video_seconds),background:'#c6ae69'}}/><b title="图片" style={{width:width(c.image_seconds)}}/></div>
  {!!(c.illustration_video_seconds||c.unclassified_video_seconds)&&<small>动画/混合示意与类型待核视频不计入实拍/录屏目标；混合方案不限制比例。<br/></small>}
  {c.legacy_video_seconds>0&&<small>手动选择（或旧项目）的视频 {seconds(c.legacy_video_seconds)} 未做实拍类型识别，按视频计入。<br/></small>}
  {warnings.length>0&&<small>{warnings.join(' · ')}</small>}
 </div>
}
function VisualQualityView({value}:{value:Shot['verification']}) {
 const q=value?.visual_quality;
 if(!q)return null;
 const names={live_action:'实拍视觉外观',screen_capture:'录屏/界面',recorded_mix:'实拍与录屏',animation:'动画/建模示意',mixed:'混合表现形式',uncertain:'类型待核'};
 return <div className="evidence-card"><strong>画面类型：{names[q.representation||'uncertain']}</strong><p>{q.quality_reason||'类型观察独立于内容审核。'}{['animation','mixed','uncertain'].includes(q.representation||'uncertain')&&' 此段不计入实拍/录屏视频目标。'}</p></div>
}
function EvidenceView({value}:{value:Shot['verification']}) {
 const e=value?.identity_evidence;
 if(!e||e.coverage==='generic')return null;
 return <div className="evidence-card"><strong>{e.status==='supported'?'人物来源依据已核对':e.status==='conflict'?'人物 / 事件证据冲突':'人物 / 事件待核实'}</strong><p>{e.reason}</p>{e.evidence?.slice(0,6).map((row,i)=><div className="evidence-row" key={i}><span>{({scoreboard:'计分牌',caption:'姓名字幕',nameplate:'姓名牌',image_caption_attribution:'原文件图注',source_title:'来源标题',source_description:'来源简介',publisher_domain:'发布者域名',event_source:'事件出处',unverified_title:'未核实标题'} as Record<string,string>)[row.kind]||row.kind}{row.frame_index!==undefined?` · 抽样 ${row.frame_index+1}`:''}</span><q>{row.quote}</q>{external(row.source_url)&&<a href={row.source_url} target="_blank" rel="noreferrer">查看出处</a>}</div>)}</div>
}
function CandidateCard({c,pid,locked,choose,preview}:{c:Candidate;pid:string;locked:boolean;choose:()=>void;preview:(start:number)=>void}) {
 const [at,setAt]=useState(c.preview?.source_clip_start||0);
 const thumb=c.thumbnail_path?fileUrl(pid,c.thumbnail_path):external(c.thumbnail_url);
 const blocked=['blocked','unsupported'].includes(c.download_status||'');
 return <div className={'candidate '+(c.kind==='video'?'video-candidate':'')}><div className="candidate-thumb">{thumb?<img loading="lazy" referrerPolicy="no-referrer" src={thumb} alt={c.title}/>:<ImageIcon size={25}/>}<span>{c.kind==='video'?'视频':'图片'}{c.duration?` · ${seconds(c.duration)}`:''}</span></div><div className="candidate-info"><h3 title={c.title}>{c.title}</h3><small>{c.publisher||sourceNames[c.provider]||c.provider}{c.published_at?` · ${String(c.published_at).slice(0,10)}`:''}</small>{!!(c.width&&c.height)&&<small>来源标称 {c.width} × {c.height} · 需实际解码确认</small>}<p title={c.license}>{c.license||'许可待确认'}</p>{c.download_reason&&<p className={blocked?'candidate-warning':''}>{c.download_reason}</p>}{c.kind==='video'&&<div className="preview-controls"><label>原视频起点<input aria-label={'预检起点 '+c.title} type="number" min="0" step="1" value={at} disabled={locked} onChange={e=>setAt(Math.max(0,Number(e.target.value)))}/></label><button className="secondary small" disabled={locked} onClick={()=>preview(at)}>小样预检</button></div>}<div><button className="secondary small" disabled={locked||blocked} onClick={choose}>{c.kind==='video'?'取所需片段':'选用图片'}</button>{external(c.source_url)&&<a aria-label="查看素材来源" href={c.source_url} target="_blank" rel="noreferrer"><ExternalLink size={14}/></a>}</div></div>{c.preview&&<div className="candidate-preview"><video controls preload="none" src={fileUrl(pid,c.preview.path)}/><div className="frame-strip">{c.preview.frames.map((f,i)=><figure key={i}><img loading="lazy" src={fileUrl(pid,f.path)} alt={`抽样 ${i+1}`}/><figcaption>{seconds(f.at)}</figcaption></figure>)}</div><small>预检 {c.preview.width}×{c.preview.height} · {(c.preview.downloaded_bytes/1024/1024).toFixed(1)} MB · {c.preview.motion_detected?'抽样画面有变化':'未检测到明显变化'}</small>{c.preflight_reason&&<p className="candidate-warning">{c.preflight_reason}</p>}{c.preview.verification&&<p>{c.preview.verification.reason}</p>}<VisualQualityView value={c.preview.verification||null}/><EvidenceView value={c.preview.verification||null}/></div>}</div>
}

function AssetMetadata({asset,busy,save}:{asset:Asset;busy:boolean;save:(v:Record<string,string>)=>void}) {
 const [v,setV]=useState({title:asset.title,description:asset.description,source_url:asset.source_url,license:asset.license});
 return <div className="metadata-fields">{[['title','标题'],['description','检索描述'],['source_url','来源网址'],['license','使用许可']].map(([key,label])=><label key={key}>{label}<input value={v[key as keyof typeof v]} onChange={e=>setV({...v,[key]:e.target.value})}/></label>)}<button className="secondary small" onClick={()=>save(v)} disabled={busy}>保存说明</button></div>
}

function ShotEditor({project,shot,index,busy,run,patch,job,upload,onProject,saveRef,onDirty}:{project:Project;shot:Shot;index:number;busy:boolean;run:(f:()=>Promise<void>)=>Promise<void>;patch:(id:string,v:Record<string,unknown>)=>Promise<void>;job:(k:string,v?:Record<string,unknown>)=>Promise<void>;upload:(f:FileList|null,r?:string,s?:string)=>Promise<void>;onProject:(p:Project)=>void;saveRef:{current:null|(()=>Promise<void>)};onDirty:(v:boolean)=>void}) {
 const editable=(s:Shot)=>({narration:s.narration,visual:s.visual,query:s.query,subject:s.subject,location:s.location,era:s.era,exclusions:s.exclusions,overlay_label:s.overlay_label||'',duration:s.duration,clip_start:s.clip_start,fit:s.fit,persons_text:(s.persons||[]).map(p=>[p.name,...p.aliases].join(' | ')).join('\n'),event:s.event||'',evidence_mode:s.evidence_mode||'generic',event_scope:s.event_scope||'exact',preferred_media:s.preferred_media||'video',source_review_note:s.source_review_note||'',source_review_url:s.source_review_url||''});
 const [edit,setEdit]=useState(editable(shot)),[dirty,setDirty]=useState(false),[pane,setPane]=useState('candidates'),[videoLink,setVideoLink]=useState('');
 useEffect(()=>{if(!dirty)setEdit(editable(shot))},[shot,dirty]);
 const field=(key:string,value:string|number)=>{setEdit({...edit,[key]:value});setDirty(true)};
 const save=async()=>{if(dirty){const {persons_text,...fields}=edit;const persons=persons_text.split('\n').map(line=>line.split('|').map(v=>v.trim()).filter(Boolean)).filter(row=>row.length).map(row=>({name:row[0],aliases:row.slice(1)}));await patch(shot.id,{...fields,persons});setDirty(false)}};
 useEffect(()=>{saveRef.current=save;onDirty(dirty);return()=>{saveRef.current=null;onDirty(false)}},[edit,dirty,shot.id]);
 const action=(fn:()=>Promise<void>)=>run(async()=>{await save();await fn()});
 const asset=project.assets.find(a=>a.id===shot.selected_asset), locked=busy||shot.locked;
 const choose=async(c:Candidate)=>action(async()=>{
   if(c.asset_id)onProject(await api<Project>(`/projects/${project.id}/shots/${shot.id}/asset/${c.asset_id}`,'POST'));
   else await job('select',{shot_id:shot.id,candidate_id:c.id});
 });
 return <div className="shot-detail"><section className="panel detail-main"><div className="panel-heading"><h2>分镜 {String(index+1).padStart(2,'0')} <span className={shot.approved?'badge green':'badge'}>{shot.approved?'已确认':'待审核'}</span></h2><button className="icon-button" title={shot.locked?'解锁分镜':'锁定分镜'} disabled={busy} onClick={()=>action(()=>patch(shot.id,{locked:!shot.locked}))}>{shot.locked?<Lock size={17}/>:<Unlock size={17}/>}</button></div><ShotPreview project={project} shot={shot} asset={asset}/>
  <div className="preview-meta"><span>{asset?.title||'尚未选择素材'}</span>{asset&&external(asset.source_url)&&<a href={asset.source_url} target="_blank" rel="noreferrer"><ExternalLink size={13}/>来源</a>}</div>
  <label>口播<textarea rows={3} value={edit.narration} disabled={locked} onChange={e=>field('narration',e.target.value)}/></label><label>画面描述<textarea rows={2} value={edit.visual} disabled={locked} onChange={e=>field('visual',e.target.value)}/></label>
  <details className="shot-constraints"><summary>主体、地域与排除条件</summary><div className="field-grid">{[['subject','主体 / 型号'],['location','地点'],['era','年代'],['exclusions','排除条件'],['overlay_label','画面标注 · 后期叠加，最多 30 字']].map(([key,label])=><label key={key}>{label}<input disabled={locked} value={String(edit[key as keyof typeof edit])} onChange={e=>field(key,e.target.value)}/></label>)}</div></details>
  <details className="shot-constraints" open={!!shot.persons?.length}><summary>人物与事件依据</summary><label>画面中需要的人物 · 每行一人，竖线后填写别名<textarea rows={2} value={edit.persons_text} disabled={locked} placeholder="梁靖崑 | Liang Jingkun&#10;郭冠宏 | Kuo Guan-Hong" onChange={e=>field('persons_text',e.target.value)}/></label><label>具体事件 / 日期 / 对阵<input value={edit.event} disabled={locked} onChange={e=>field('event',e.target.value)}/></label><div className="field-grid"><label>核对要求<select value={edit.evidence_mode} disabled={locked} onChange={e=>field('evidence_mode',e.target.value)}><option value="generic">通用画面</option><option value="person">指定人物</option><option value="event">指定事件</option></select></label><label>画面用途<select value={edit.event_scope} disabled={locked} onChange={e=>field('event_scope',e.target.value)}><option value="exact">本场 / 本次事件</option><option value="background">资料画面 · 需叠加标注</option></select></label></div><small className="muted-note">核对原始来源、字幕和计分牌姓名；标题提到一个人不足以证明画面对应。资料画面不当作本场。</small></details><div className="field-grid three"><label>时长（秒）<input type="number" step="0.04" min="1" max="120" value={edit.duration} disabled={locked||!!shot.audio} onChange={e=>field('duration',Number(e.target.value))}/></label><label>素材起点（秒）<input type="number" step="0.1" min="0" value={edit.clip_start} disabled={locked||asset?.kind!=='video'} onChange={e=>field('clip_start',Number(e.target.value))}/></label><label>画面适配<select value={edit.fit} disabled={locked} onChange={e=>field('fit',e.target.value)}><option value="cover">填满画面</option><option value="contain">保留完整画面</option></select></label></div>
  {shot.audio&&<audio className="audio-player" controls src={fileUrl(project.id,shot.audio.path)}/>}
  <div className="shot-actions"><button className="secondary small" disabled={locked||!dirty} onClick={()=>run(save)}><Save size={14}/>保存修改</button><label className={'secondary small '+(locked?'disabled':'')}><Upload size={14}/>导入配音<input hidden type="file" accept="audio/*,video/mp4" disabled={locked} onChange={e=>{upload(e.target.files,'voice',shot.id);e.target.value=''}}/></label><button className="secondary small" disabled={locked||!!project.full_audio} onClick={()=>action(()=>job('voice',{shot_id:shot.id,replace:!!shot.audio}))}><Mic size={14}/>{shot.audio?'重做配音':'生成配音'}</button></div>
  </section><section className="panel candidate-panel"><div className="panel-heading"><h2>为画面找到依据</h2><Search size={18}/></div><div className="mini-tabs"><button className={pane==='candidates'?'active':''} onClick={()=>setPane('candidates')}>搜索候选</button><button className={pane==='local'?'active':''} onClick={()=>setPane('local')}>项目素材</button></div>
  {pane==='candidates'?<><details className="manual-source"><summary>粘贴已有视频链接</summary><input aria-label="视频来源网址" value={videoLink} onChange={e=>setVideoLink(e.target.value)} placeholder="官方视频原页或公开 MP4 地址" disabled={locked}/><button className="secondary small full" style={{marginTop:8}} disabled={locked||!external(videoLink)} onClick={()=>action(async()=>{onProject(await api<Project>(`/projects/${project.id}/shots/${shot.id}/video-link`,'POST',{url:videoLink,title:'指定视频来源'}));setVideoLink('')})}>加入候选，先做片段预检</button></details><div className="search-row"><input aria-label="素材搜索词" value={edit.query} disabled={locked} onChange={e=>field('query',e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!locked)action(()=>job('search',{shot_id:shot.id}))}}/><button title="搜索当前镜头" className="primary small" disabled={locked} onClick={()=>action(()=>job('search',{shot_id:shot.id}))}><Search size={16}/></button></div><button className="secondary small full" disabled={locked} onClick={()=>action(()=>job('match',{shot_id:shot.id,replace:true}))}><Sparkles size={14}/>AI 自动匹配此镜头</button><p className="muted-note">{shot.search_note||(shot.search_queries?.length?`检索词：${shot.search_queries.join(' / ')}。`:'')+'先比较预览，再检查小片段中的动作、清晰度与来源；通过后才下载所需片段。'}</p><div className="candidates">{shot.candidates.map(c=><CandidateCard key={c.id} c={c} pid={project.id} locked={locked} choose={()=>choose(c)} preview={start=>action(()=>job('preview',{shot_id:shot.id,candidate_id:c.id,clip_start:start}))}/>)}</div>{!shot.candidates.length&&<div className="small-empty"><Search size={26}/><p>先搜索几个具体的关键词</p><small>人物、型号、地点和动作通常更有帮助</small></div>}</>:<><label className={'upload-zone '+(locked?'disabled':'')}><Upload size={20}/><span>导入图片或视频</span><small>支持多选，素材保存在本机</small><input type="file" multiple accept="image/jpeg,image/png,image/webp,video/*" hidden disabled={locked} onChange={e=>{upload(e.target.files);e.target.value=''}}/></label><div className="local-candidates">{project.assets.filter(a=>a.kind!=='audio').map(a=><button disabled={locked} key={a.id} onClick={()=>choose({id:'local-'+a.id,asset_id:a.id,title:a.title,provider:'local',source_url:a.source_url,license:a.license,kind:a.kind})}><img src={fileUrl(project.id,a.thumbnail||a.path)} alt={a.title}/><span>{a.title}</span>{a.id===shot.selected_asset&&<Check size={17}/>}</button>)}</div></>}
  <div className="review-box"><div><ShieldCheck size={18}/><strong>画面审核</strong></div>{shot.verification?<p className={'verdict '+shot.verification.verdict}>{({match:'画面基本相符',uncertain:'仍需核实',mismatch:'发现不匹配'} as Record<string,string>)[shot.verification.verdict]}：{shot.verification.reason}{!!shot.verification.conflicts?.length&&<><br/>冲突：{shot.verification.conflicts.join("；")}</>}</p>:<p>检查主体、年代、地点和具体片段。视觉模型结论仅供参考。</p>}<VisualQualityView value={shot.verification}/><EvidenceView value={shot.verification}/>{(!!shot.persons?.length||edit.evidence_mode!=='generic'||!!edit.event)&&<details className="manual-source"><summary>记录人工核对依据</summary><label>核对的原始来源网址<input value={edit.source_review_url} disabled={locked} placeholder="https://…" onChange={e=>field('source_review_url',e.target.value)}/></label><label>依据说明<textarea rows={3} value={edit.source_review_note} disabled={locked} placeholder="例如：原视频第 25 秒计分牌有双方全名，赛事、日期和对阵与该镜一致。" onChange={e=>field('source_review_note',e.target.value)}/></label><small>自动证据不足时，必须记录来源和核对说明后才能确认。</small></details>}<button className="secondary small full" disabled={locked||!asset} onClick={()=>action(()=>job('verify',{shot_id:shot.id}))}><Sparkles size={14}/>AI 检查选定画面</button><button className={'full '+(shot.approved?'approved-button':'primary')} disabled={locked||!asset} onClick={()=>action(()=>patch(shot.id,{approved:!shot.approved}))}><CheckCircle2 size={16}/>{shot.approved?'已确认 · 点击撤回':'我已核对，确认此画面'}</button></div>
  </section></div>
}

function SettingsModal({close,onError}:{close:()=>void;onError:(s:string)=>void}) {
 const [browserMsg,setBrowserMsg]=useState(''),[opening,setOpening]=useState(false);
 const [values,setValues]=useState<Record<string,any>>({}),[saving,setSaving]=useState(false),[loaded,setLoaded]=useState(false);
 useEffect(()=>{api<Record<string,any>>('/settings').then(v=>{setValues(v);setLoaded(true)}).catch(e=>onError(e.message))},[]);
 const set=(k:string,v:string)=>setValues({...values,[k]:v});
 const field=(k:string,label:string,secret=false)=><label key={k}>{label}<input type={secret?'password':'text'} autoComplete="off" value={values[k]||''} placeholder={secret?(values[k+'_set']?'已保存，留空保留原密钥':'填写 API Key'):''} onChange={e=>set(k,e.target.value)}/></label>;
 const save=async()=>{setSaving(true);try{const payload:Record<string,string>={};for(const [k,v] of Object.entries(values)){if(k.endsWith('_set'))continue;if(k.endsWith('api_key')&&!v)continue;payload[k]=String(v)}await api('/settings','PATCH',payload);close()}catch(e){onError((e as Error).message)}finally{setSaving(false)}};
 return <div className="modal-backdrop"><section role="dialog" aria-modal="true" aria-label="服务与设置" className="modal settings-modal"><div className="modal-heading"><div><h2>服务与设置</h2></div><button className="icon-button" aria-label="关闭设置" onClick={close}><X size={21}/></button></div><div className="modal-content"><section><h3><Sparkles size={17}/>文稿与视觉模型</h3><p>支持 DeepSeek、阿里云通义等兼容 Chat Completions 的服务。自动配素材和检查画面时，会向配置的模型服务发送候选预览与选定素材的抽样图像。</p>{field('model_base_url','接口基础地址')}{field('model_api_key','API Key',true)}<div className="field-grid">{field('model_name','文稿模型')}{field('vision_model','视觉模型')}</div></section><ModelRouting values={values} change={set}/><CostSettings values={values} change={set}/><section><h3><Search size={17}/>素材搜索</h3><label>在线渠道<select value={values.search_provider||'mixed'} onChange={e=>set('search_provider',e.target.value)}><option value="mixed">多源素材 · 视频优先，图片补充</option><option value="video">多源素材 · 仅检索视频</option><option value="local">只搜索项目素材</option></select></label><label>镜头长度<select value={values.shot_length||'long'} onChange={e=>set('shot_length',e.target.value)}><option value="long">约 6 秒一个镜头（推荐：找画面快、重复少）</option><option value="medium">约 4 秒一个镜头</option><option value="line">每行字幕一个镜头（约 2.5 秒，长稿最慢）</option></select></label><p>快速流程（默认）：B 站长视频实拍素材 + Pixabay 图库，模型批量看缩略图选片并抽检成片。普通画面大致相关即可；具名人物只用标题含姓名的来源，找不到时改用不含人物的相关画面。</p><StockKeys values={values} change={set}/><BilibiliLogin/></section><section><h3><Mic size={17}/>配音</h3><label>配音方式<select value={values.tts_provider||'edge_tts'} onChange={e=>set('tts_provider',e.target.value)}><option value="edge_tts">免费配音 · 微软神经网络音色（推荐，不收费）</option><option value="qwen_tts">千问配音 · 与上面的百炼密钥共用，约 ¥0.16 / 千字</option><option value="system">系统中文语音 · 本地免费，音质一般</option><option value="import">只用导入的配音文件</option><option value="compatible">其他 audio/speech 接口</option></select></label>{['edge_tts','qwen_tts'].includes(values.tts_provider||'edge_tts')&&<VoicePicker provider={values.tts_provider||'edge_tts'} values={values} change={set}/>}{(values.tts_provider||'edge_tts')==='edge_tts'&&<p>使用微软 Edge 浏览器「大声朗读」的神经网络音色，不需要 Key、不收费；它不是微软公开售卖的接口，若哪天不可用，请改用千问配音。</p>}{values.tts_provider==='qwen_tts'&&<><p>阿里云百炼 qwen3-tts-flash，按字数计费，约 ¥0.16 / 千字。配音费用单独计算，不占用下面的模型预算。</p>{field('tts_daily_budget_cny','每日配音费用上限（元）')}</>}{values.tts_provider==='compatible'&&<>{field('tts_base_url','配音接口地址')}{field('tts_api_key','配音 API Key',true)}<div className="field-grid">{field('tts_model','配音模型')}{field('tts_voice','音色名称')}</div></>}</section><SubtitleSettings values={values} change={set}/><NewsCrawlerSettings values={values} change={set}/><section><h3><Monitor size={17}/>合成与保存</h3><GpuStatus/><AssistBox/><label>成片保存位置<span className="input-with-button"><input value={values.export_dir||''} placeholder="留空：视频（Videos）文件夹下的「镜稿成片」" onChange={e=>set('export_dir',e.target.value)}/><button type="button" className="secondary small" onClick={async()=>{try{const r=await fetch('/api/output-folder/choose',{method:'POST'});const d=await r.json();if(d.changed)set('export_dir',d.path)}catch{/* typed path still works */}}}><FolderOpen size={14}/>选择…</button></span></label><label className="checkbox"><input type="checkbox" checked={(values.auto_save_exports||'1')==='1'} onChange={e=>set('auto_save_exports',e.target.checked?'1':'0')}/>生成完成后自动把 MP4 保存到这个文件夹（字幕放在其中的「外挂字幕」子文件夹）</label><label>视频编码<select value={values.encoder||'auto'} onChange={e=>set('encoder',e.target.value)}><option value="auto">自动 · NVIDIA 可用时优先</option><option value="cpu">CPU · 兼容模式</option><option value="nvenc">NVIDIA NVENC · 要求驱动可用</option></select></label><div className="field-grid">{[['video_workers','同时制作几条视频','3'],['plan_workers','分镜并发','3'],['match_workers','素材匹配并发','3'],['render_workers','渲染并发','3']].map(([key,label,initial])=><label key={key}>{label}<select value={values[key]||initial} onChange={e=>set(key,e.target.value)}>{(key==='video_workers'?[1,2,3,4,5,6]:[1,2,3,4]).map(n=><option key={n} value={String(n)}>{n} {key==='video_workers'?'条':'路'}</option>)}</select></label>)}</div><p>批量时默认同时制作 3 条视频（最多 6 条），它们共用同一份 B 站、配音、显卡编码和 CPU 转码的名额，所以条数调高不会把电脑占满，只是多条视频交替使用网络和模型。显卡加速开启时推荐 4 条。每条视频内部默认同时规划 3 批、检索核验 3 路、合成 3 镜；相同人物与事件共用素材检索。云端模型请求最多 6 路；千问配音最多 3 路并发。网络或服务限流时可降为 1 路。</p><p>适配 Win10 与 RTX 3060。项目和设置保存在本机，发行包不会包含你的密钥。</p></section></div><div className="modal-footer"><button className="secondary" onClick={close}>取消</button><button className="primary" disabled={!loaded||saving} onClick={save}>{saving?<Loader2 className="spin" size={16}/>:<Save size={16}/>}保存设置</button></div></section></div>
}

function ExportModal({close,preview,project,submit}:{close:()=>void;preview:()=>void;project:Project;submit:(v:Record<string,unknown>)=>void}) {
 const [resolution,setResolution]=useState('1080p'),[silent,setSilent]=useState(false),[volume,setVolume]=useState(.12),[motion,setMotion]=useState(true),[burn,setBurn]=useState(project.burn_subtitles!==false);
 const missing=project.shots.filter(s=>!s.selected_asset||!s.approved).length;
 const noAudio=!project.full_audio&&project.shots.some(s=>!s.audio);
 const coverage=composition(project), blockedCoverage=coverage.identity_pending.length>0||(project.media_policy!=='mixed'&&(!coverage.meets_target||coverage.short_video_shots.length>0||coverage.low_resolution_shots.length>0));
 return <div className="modal-backdrop"><section className="modal export-modal" role="dialog" aria-modal="true" aria-label="导出视频"><div className="modal-heading"><div><h2>导出视频</h2></div><button className="icon-button" aria-label="关闭导出" onClick={close}><X size={20}/></button></div><div className="modal-content"><p>中文字幕直接烧录进 MP4，同时提供独立 SRT 字幕及素材来源清单。后台合成时可以关闭浏览器页面。</p><label>分辨率<select value={resolution} onChange={e=>setResolution(e.target.value)}><option value="1080p">1080p · 正式导出</option><option value="720p">720p · 快速预览</option></select></label><CompositionBar project={project}/><label className="checkbox"><input type="checkbox" checked={motion} disabled={project.media_policy!=='mixed'} onChange={e=>setMotion(e.target.checked)}/>少量照片缓慢运镜（完整显示模式也保留画面运动）</label>{project.music&&<label>背景音乐音量 {Math.round(volume*100)}%<input type="range" min="0" max="0.5" step="0.01" value={volume} onChange={e=>setVolume(Number(e.target.value))}/></label>}<label className="checkbox"><input type="checkbox" checked={burn} onChange={e=>setBurn(e.target.checked)}/>画面上烧录字幕（不勾选时只附 SRT 字幕文件，适合导入剪映）</label><label className="checkbox"><input type="checkbox" checked={silent} onChange={e=>setSilent(e.target.checked)}/>允许缺少配音的镜头以静音预览导出</label>{missing>0&&<div className="inline-note warning">还有 {missing} 个镜头未选择或未确认素材。</div>}{noAudio&&!silent&&<div className="inline-note warning">部分镜头缺少配音，请生成或导入音频。</div>}<small className="muted-note">字幕时间按镜头音频时长与文字长度估算。整段配音导入后请先核对各镜节奏。</small></div><div className="modal-footer"><button className="text-link film-link" onClick={preview}><Play size={13}/>先预览全片</button><button className="secondary" onClick={close}>返回检查</button><button className="primary" disabled={missing>0||(noAudio&&!silent)||blockedCoverage||!!project.script_changed} onClick={()=>submit({resolution,allow_silent:silent,music_volume:volume,image_motion:motion,subtitles:burn})}><Clapperboard size={17}/>开始合成</button></div></section></div>
}

createRoot(document.getElementById('root')!).render(<StrictMode><App/></StrictMode>);
